Here is the commit message:
usb: aqc111: stop lying about skb->truesize

Some usb drivers try to set small skb->truesize and break
core networking stacks.

I replace one skb_clone() by an allocation of a fresh
and small skb, to get minimally sized skbs, like we did
in commit 1e2c61172342 ("net: cdc_ncm: reduce skb truesize
in rx path") and 4ce62d5b2f7a ("net: usb: ax88179_178a:
stop lying about skb->truesize")

Fixes: 361459cd9642 ("net: usb: aqc111: Implement RX data path")
Signed-off-by: Eric Dumazet <edumazet@google.com>
Link: https://lore.kernel.org/r/20240506135546.3641185-1-edumazet@google.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The bug arises from the incorrect handling of the `skb->truesize` property in the `aqc111` USB driver, where the driver was cloning an existing socket buffer (skb) instead of allocating a new one. This led to the `truesize` of the cloned skb being inaccurately reported, which could disrupt the core networking stack's operations that rely on accurate size information for memory management and performance optimization.

Here is the patch:

 static int aqc111_rx_fixup(struct usbnet *dev, struct sk_buff *skb)
 {
 	struct aqc111_data *aqc111_data = dev->driver_priv;
 	struct sk_buff *new_skb = NULL;
 	u32 pkt_total_offset = 0;
 	u64 *pkt_desc_ptr = NULL;
 	u32 start_of_descs = 0;
 	u32 desc_offset = 0; /*RX Header Offset*/
 	u16 pkt_count = 0;
 	u64 desc_hdr = 0;
 	u16 vlan_tag = 0;
 	u32 skb_len;

 	if (!skb)
 		goto err;

 	skb_len = skb->len;
 	if (skb_len < sizeof(desc_hdr))
 		goto err;

 	/* RX Descriptor Header */
 	skb_trim(skb, skb_len - sizeof(desc_hdr));
 	desc_hdr = le64_to_cpup((u64 *)skb_tail_pointer(skb));

 	/* Check these packets */
 	desc_offset = (desc_hdr & AQ_RX_DH_DESC_OFFSET_MASK) >>
 		      AQ_RX_DH_DESC_OFFSET_SHIFT;
 	pkt_count = desc_hdr & AQ_RX_DH_PKT_CNT_MASK;
 	start_of_descs = skb_len - ((pkt_count + 1) *  sizeof(desc_hdr));

 	/* self check descs position */
 	if (start_of_descs != desc_offset)
 		goto err;

 	/* self check desc_offset from header and make sure that the
 	 * bounds of the metadata array are inside the SKB
 	 */
 	if (pkt_count * 2 + desc_offset >= skb_len)
 		goto err;

 	/* Packets must not overlap the metadata array */
 	skb_trim(skb, desc_offset);

 	if (pkt_count == 0)
 		goto err;

 	/* Get the first RX packet descriptor */
 	pkt_desc_ptr = (u64 *)(skb->data + desc_offset);

 	while (pkt_count--) {
 		u64 pkt_desc = le64_to_cpup(pkt_desc_ptr);
 		u32 pkt_len_with_padd = 0;
 		u32 pkt_len = 0;

 		pkt_len = (u32)((pkt_desc & AQ_RX_PD_LEN_MASK) >>
 			  AQ_RX_PD_LEN_SHIFT);
 		pkt_len_with_padd = ((pkt_len + 7) & 0x7FFF8);

 		pkt_total_offset += pkt_len_with_padd;
 		if (pkt_total_offset > desc_offset ||
 		    (pkt_count == 0 && pkt_total_offset != desc_offset)) {
 			goto err;
 		}

 		if (pkt_desc & AQ_RX_PD_DROP ||
 		    !(pkt_desc & AQ_RX_PD_RX_OK) ||
 		    pkt_len > (dev->hard_mtu + AQ_RX_HW_PAD)) {
 			skb_pull(skb, pkt_len_with_padd);
 			/* Next RX Packet Descriptor */
 			pkt_desc_ptr++;
 			continue;
 		}

-		/* Clone SKB */
-		new_skb = skb_clone(skb, GFP_ATOMIC);
+		new_skb = netdev_alloc_skb_ip_align(dev->net, pkt_len);

 		if (!new_skb)
 			goto err;

-		new_skb->len = pkt_len;
+		skb_put(new_skb, pkt_len);
+		memcpy(new_skb->data, skb->data, pkt_len);
 		skb_pull(new_skb, AQ_RX_HW_PAD);
-		skb_set_tail_pointer(new_skb, new_skb->len);

-		new_skb->truesize = SKB_TRUESIZE(new_skb->len);
 		if (aqc111_data->rx_checksum)
 			aqc111_rx_checksum(new_skb, pkt_desc);

 		if (pkt_desc & AQ_RX_PD_VLAN) {
 			vlan_tag = pkt_desc >> AQ_RX_PD_VLAN_SHIFT;
 			__vlan_hwaccel_put_tag(new_skb, htons(ETH_P_8021Q),
 					       vlan_tag & VLAN_VID_MASK);
 		}

 		usbnet_skb_return(dev, new_skb);
 		if (pkt_count == 0)
 			break;

 		skb_pull(skb, pkt_len_with_padd);

 		/* Next RX Packet Header */
 		pkt_desc_ptr++;

 		new_skb = NULL;
 	}

 	return 1;

 err:
 	return 0;
 }



